import * as cheerio from "cheerio";
import type { FeedConfig, FeedItem, ScraperHelpers } from "../../types.js";

function parseDate(dateStr: string): string {
  // e.g. "May 14, 2026" -> ISO-8601
  const d = new Date(dateStr);
  if (!isNaN(d.getTime())) {
    return d.toISOString();
  }
  return new Date().toISOString();
}

export async function fetchFeed(
  config: FeedConfig,
  helpers: ScraperHelpers
): Promise<FeedItem[]> {
  // Fetch the listing page
  const listingHtml = await fetch(config.url).then((r) => r.text());
  const $list = cheerio.load(listingHtml);

  const items: { title: string; url: string; dateText: string }[] = [];

  $list(".blog_cms_item").each((_i, el) => {
    const card = $list(el);
    const link = card.find("a").first();
    const href = link.attr("href") || "";
    const url = href.startsWith("http")
      ? href
      : `https://claude.com${href}`;

    const dateText = card.find(".u-text-style-caption").first().text().trim();
    const title = card.find(".card_blog_title").text().trim();

    if (title && url) {
      items.push({ title, url, dateText });
    }
  });

  // Fetch each detail page in parallel to get image and full content
  const detailResults = await Promise.all(
    items.map(async (item) => {
      try {
        const detailHtml = await fetch(item.url).then((r) => r.text());
        const $detail = cheerio.load(detailHtml);

        // Extract og:image — first <meta property="og:image"> is the per-post image
        let imageUrl: string | undefined;
        const ogImages = $detail('meta[property="og:image"]');
        if (ogImages.length > 0) {
          const first = ogImages.first().attr("content");
          if (first) {
            // Resolve relative URL if needed
            imageUrl = first.startsWith("http")
              ? first
              : new URL(first, item.url).href;
          }
        }

        // Extract full content from .u-rich-text-blog
        let contentHtml: string | undefined;
        const richText = $detail(".u-rich-text-blog").first();
        if (richText.length > 0) {
          contentHtml = richText.html() ?? undefined;
        }

        return { imageUrl, contentHtml };
      } catch {
        // Single failure degrades gracefully
        return { imageUrl: undefined, contentHtml: undefined };
      }
    })
  );

  // Build feed items
  const feedItems: FeedItem[] = items.map((item, idx) => {
    const detail = detailResults[idx];
    return {
      id: item.url,
      title: item.title,
      url: item.url,
      publishedAt: parseDate(item.dateText),
      source: config.slug,
      imageUrl: detail?.imageUrl,
      contentHtml: detail?.contentHtml,
    };
  });

  return feedItems;
}
